// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// CallsList Call summaries
	// (GET /api/operations/v1/calls)
	CallsList(ctx context.Context, request CallsListRequestObject) (CallsListResponseObject, error)
	// CallGet One call's trace
	// (GET /api/operations/v1/calls/{call_id})
	CallGet(ctx context.Context, request CallGetRequestObject) (CallGetResponseObject, error)
	// OperationLogList The credential's own operation log
	// (GET /api/operations/v1/log)
	OperationLogList(ctx context.Context, request OperationLogListRequestObject) (OperationLogListResponseObject, error)
	// Whoami The credential itself
	// (GET /api/operations/v1/me)
	Whoami(ctx context.Context, request WhoamiRequestObject) (WhoamiResponseObject, error)
	// ModelsList Models
	// (GET /api/operations/v1/models)
	ModelsList(ctx context.Context, request ModelsListRequestObject) (ModelsListResponseObject, error)
	// ModelGet One model
	// (GET /api/operations/v1/models/{model_id})
	ModelGet(ctx context.Context, request ModelGetRequestObject) (ModelGetResponseObject, error)
	// PendingMappingsList Upstream model names waiting to be mapped
	// (GET /api/operations/v1/pending-mappings)
	PendingMappingsList(ctx context.Context, request PendingMappingsListRequestObject) (PendingMappingsListResponseObject, error)
	// SuppliersList Suppliers
	// (GET /api/operations/v1/suppliers)
	SuppliersList(ctx context.Context, request SuppliersListRequestObject) (SuppliersListResponseObject, error)
	// SuppliersGet One supplier
	// (GET /api/operations/v1/suppliers/{supplier_id})
	SuppliersGet(ctx context.Context, request SuppliersGetRequestObject) (SuppliersGetResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

